/**
 * Tier-2 text, regex, and JSON builders for the calc DSL.
 *
 * All functions in this module produce or consume `Expr<"text">`. They
 * follow the same shape as tier-1: each builder coerces its inputs
 * through `coerce()`, composes their `toCalcString()` outputs into the
 * wire form, and brands the result.
 *
 * Type rules baked in:
 *   - `concat` accepts the scalar families Knowhere can stringify directly:
 *     date, datetime, decimal, number, boolean, and text.
 *   - `len` accepts text only (server rejects numeric).
 *   - `regexMatch` returns bool; the rest return text.
 *   - Argument naming favors readability over wire-form parity
 *     (`needle` / `haystack` for FIND/SEARCH; `pattern` for regex).
 */
import { coerce, expressionContext, makeComposedExpr, makeExpr } from "./runtime.js";
// ---------------------------------------------------------------------------
// CONCAT / TEXT — assembling text values
// ---------------------------------------------------------------------------
/**
 * Concatenate two or more expressions into a single text value.
 * Non-text expressions are stringified by the server. At least two
 * args are required — wire `CONCAT` rejects a single-arg call.
 */
export function concat(a, b, ...rest) {
    const exprs = [a, b, ...rest].map((v) => coerce(v));
    return makeComposedExpr("text", exprs, () => `CONCAT(${exprs.map((e) => e.toCalcString()).join(", ")})`);
}
/**
 * Coerce any expression to text. Wire `TEXT(value)`. Useful for
 * embedding non-text values inside a string-shaped expression where
 * the server's implicit promotion isn't enough.
 */
export function toText(value) {
    const e = coerce(value);
    return makeComposedExpr("text", [e], () => `TEXT(${e.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// LEN / TRIM / case
// ---------------------------------------------------------------------------
/** Character length of a text expression. Returns NUMBER. */
export function len(value) {
    const e = coerce(value);
    return makeComposedExpr("number", [e], () => `LEN(${e.toCalcString()})`);
}
/** Strip leading/trailing whitespace. */
export function trim(value) {
    const e = coerce(value);
    return makeComposedExpr("text", [e], () => `TRIM(${e.toCalcString()})`);
}
/** Upper-case. */
export function upper(value) {
    const e = coerce(value);
    return makeComposedExpr("text", [e], () => `UPPER(${e.toCalcString()})`);
}
/** Lower-case. */
export function lower(value) {
    const e = coerce(value);
    return makeComposedExpr("text", [e], () => `LOWER(${e.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// LEFT / RIGHT / MID — substring helpers
// ---------------------------------------------------------------------------
/**
 * Leftmost `n` characters of a text expression. `n` defaults to 1 on
 * the server when omitted. Wire emits `LEFT(text)` or `LEFT(text, n)`.
 */
export function left(value, n) {
    const e = coerce(value);
    if (n === undefined) {
        return makeComposedExpr("text", [e], () => `LEFT(${e.toCalcString()})`);
    }
    const ne = coerce(n);
    return makeComposedExpr("text", [e, ne], () => `LEFT(${e.toCalcString()}, ${ne.toCalcString()})`);
}
/**
 * Rightmost `n` characters of a text expression. `n` defaults to 1 on
 * the server when omitted.
 */
export function right(value, n) {
    const e = coerce(value);
    if (n === undefined) {
        return makeComposedExpr("text", [e], () => `RIGHT(${e.toCalcString()})`);
    }
    const ne = coerce(n);
    return makeComposedExpr("text", [e, ne], () => `RIGHT(${e.toCalcString()}, ${ne.toCalcString()})`);
}
/**
 * Substring from `start` (1-indexed) for `length` characters. Wire
 * emits `MID(text, start, length)`.
 */
export function mid(value, start, length) {
    const e = coerce(value);
    const se = coerce(start);
    const le = coerce(length);
    return makeComposedExpr("text", [e, se, le], () => `MID(${e.toCalcString()}, ${se.toCalcString()}, ${le.toCalcString()})`);
}
/**
 * Replace every occurrence of `find` with `replace` in `value`. Wire
 * emits `SUBSTITUTE(value, find, replace)`. For pattern-based
 * replacement use `regexReplace`.
 */
export function substitute(value, find, replace) {
    const v = coerce(value);
    const f = coerce(find);
    const r = coerce(replace);
    return makeComposedExpr("text", [v, f, r], () => `SUBSTITUTE(${v.toCalcString()}, ${f.toCalcString()}, ${r.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// FIND / SEARCH — substring location
// ---------------------------------------------------------------------------
/**
 * Case-sensitive index of `needle` within `haystack` (1-indexed).
 * `start` is the 1-indexed position to begin searching from. Wire:
 * `FIND(needle, haystack)` / `FIND(needle, haystack, start)`.
 */
export function find(needle, haystack, start) {
    const n = coerce(needle);
    const h = coerce(haystack);
    if (start === undefined) {
        return makeComposedExpr("number", [n, h], () => `FIND(${n.toCalcString()}, ${h.toCalcString()})`);
    }
    const s = coerce(start);
    return makeComposedExpr("number", [n, h, s], () => `FIND(${n.toCalcString()}, ${h.toCalcString()}, ${s.toCalcString()})`);
}
/**
 * Case-INsensitive variant of `find`. Wire: `SEARCH(...)`.
 */
export function search(needle, haystack, start) {
    const n = coerce(needle);
    const h = coerce(haystack);
    if (start === undefined) {
        return makeComposedExpr("number", [n, h], () => `SEARCH(${n.toCalcString()}, ${h.toCalcString()})`);
    }
    const s = coerce(start);
    return makeComposedExpr("number", [n, h, s], () => `SEARCH(${n.toCalcString()}, ${h.toCalcString()}, ${s.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// SPLIT
// ---------------------------------------------------------------------------
/**
 * Split a text expression by a separator. Wire `SPLIT(text, sep)`.
 * The server returns a text array internally; in expression context
 * it surfaces as a multi-valued text. Note the method name
 * `splitText` to avoid colliding with Array.prototype.split or the
 * JS keyword `split` in `calc.split` — `splitText` reads cleanly in
 * the calc namespace.
 */
/** @deprecated Prefer {@link split}. */
export function splitText(value, separator) {
    const v = coerce(value);
    const s = coerce(separator);
    return makeExpr("text", () => `SPLIT(${v.toCalcString()}, ${s.toCalcString()})`, {
        cardinality: "multiple",
        context: expressionContext([v, s]),
    });
}
/** Canonical concise name for the multi-valued SPLIT function. */
export const split = splitText;
// ---------------------------------------------------------------------------
// REGEX
// ---------------------------------------------------------------------------
/**
 * Regex match test. Wire `REGEXMATCH(text, pattern)` or
 * `REGEXMATCH(text, pattern, TRUE)` for case-insensitive matching.
 * The `ignoreCase` flag is a bool literal on the wire — TS accepts a
 * raw boolean here so the agent doesn't have to wrap it.
 */
export function regexMatch(value, pattern, options) {
    const v = coerce(value);
    const p = coerce(pattern);
    const ignoreCase = typeof options === "boolean" ? options : options?.ignoreCase;
    if (ignoreCase === undefined) {
        return makeComposedExpr("bool", [v, p], () => `REGEXMATCH(${v.toCalcString()}, ${p.toCalcString()})`);
    }
    return makeComposedExpr("bool", [v, p], () => `REGEXMATCH(${v.toCalcString()}, ${p.toCalcString()}, ${ignoreCase ? "TRUE" : "FALSE"})`);
}
/**
 * Regex search-and-replace. Wire `REGEXREPLACE(text, pattern, repl)`
 * or `REGEXREPLACE(text, pattern, repl, TRUE)` for case-insensitive.
 */
export function regexReplace(value, pattern, replacement, options) {
    const v = coerce(value);
    const p = coerce(pattern);
    const r = coerce(replacement);
    const ignoreCase = typeof options === "boolean" ? options : options?.ignoreCase;
    if (ignoreCase === undefined) {
        return makeComposedExpr("text", [v, p, r], () => `REGEXREPLACE(${v.toCalcString()}, ${p.toCalcString()}, ${r.toCalcString()})`);
    }
    return makeComposedExpr("text", [v, p, r], () => `REGEXREPLACE(${v.toCalcString()}, ${p.toCalcString()}, ${r.toCalcString()}, ${ignoreCase ? "TRUE" : "FALSE"})`);
}
/**
 * Regex extract — returns the first matching substring (or capture
 * group) as text. Wire `REGEXEXTRACT(text, pattern)`.
 */
export function regexExtract(value, pattern) {
    const v = coerce(value);
    const p = coerce(pattern);
    return makeComposedExpr("text", [v, p], () => `REGEXEXTRACT(${v.toCalcString()}, ${p.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// JSON escape helpers
// ---------------------------------------------------------------------------
/** Escape a text value for embedding in a JSON string literal. */
export function jsonEscape(value) {
    const e = coerce(value);
    return makeComposedExpr("text", [e], () => `JSON_ESCAPE(${e.toCalcString()})`);
}
/** Reverse the effect of `jsonEscape` — decode a JSON-escaped string. */
export function jsonUnescape(value) {
    const e = coerce(value);
    return makeComposedExpr("text", [e], () => `JSON_UNESCAPE(${e.toCalcString()})`);
}
/** Repeat text a whole-number count of times. Wire `REPT(text, count)`. */
export function repeat(value, count) {
    const v = coerce(value);
    const c = coerce(count);
    return makeComposedExpr("text", [v, c], () => `REPT(${v.toCalcString()}, ${c.toCalcString()})`);
}
